CREATE TABLE #Features (
    feature_id  INT NOT NULL PRIMARY KEY,
    feature_name VARCHAR(50) NOT NULL,
    is_enabled  BIT NULL
);

INSERT INTO #Features (feature_id, feature_name, is_enabled)
VALUES (1, 'search', 1), (2, 'export', 0), (3, 'beta-ui', NULL);

SELECT
    SUM(CASE WHEN is_enabled = 1 THEN 1 ELSE 0 END) AS enabled_count,
    SUM(CASE WHEN is_enabled = 0 THEN 1 ELSE 0 END) AS disabled_count,
    SUM(CASE WHEN is_enabled IS NULL THEN 1 ELSE 0 END) AS unknown_count
FROM #Features;
